const sabDur = (sec) => { const m = Math.round(sec / 60); return m % 60 ? `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, "0")}` : `${m / 60} h`; };
const sabDone = (k) => (E.sabEarnLeft(S, k) ? "" : " (déjà reçu aujourd'hui)");
