  let z = cur && inTier(cur) ? cur.zone : null;
  if (!z) { const top = topTeamLvl(); let best = null;
    ZONES.forEach((zz) => zz.subs.forEach((s) => { if (inTier(s) && E.subUnlocked(S, s.id) && s.lvl[0] <= top + 3 && (!best || s.lvl[0] > best[0].lvl[0])) best = [s, zz.id]; }));
    z = best ? best[1] : null; }
