  const fresh = []; for (let u = from; u < S.nextUid; u++) { const it = S.items[u]; const T = it && ITEMS[it.tpl]; if (T && !T.trophy && T.slot !== "dofus" && !E.equippedBy(S, u)) fresh.push(it); }
