document.addEventListener("keydown", (ev) => {
  if (!S) return; const k = ev.key;
  if ((ev.ctrlKey || ev.metaKey) && !ev.altKey && (k === "k" || k === "K")) { ev.preventDefault(); if ($("#wsearch")) searchClose(); else { closeSheet(); searchOpen(); } return; }
  if ($("#wsearch")) {
    if (k === "Escape") { ev.preventDefault(); searchClose(); } else if (k === "ArrowDown" || k === "ArrowUp") { ev.preventDefault(); searchMove(k === "ArrowDown" ? 1 : -1); } else if (k === "Enter") { ev.preventDefault(); if (!(ev.shiftKey && searchMonKey())) searchEnter(); } else if (k === "ArrowRight" && $("#wsq") && $("#wsq").selectionStart === $("#wsq").value.length && searchMonKey()) ev.preventDefault();
    return;
  }
  if (document.activeElement && (document.activeElement.id === "navq" || document.activeElement.id === "navqm")) { // 1.2 (7A) : Entrée ouvre la première page trouvée, Échap vide la case
    if (k === "Enter") { ev.preventDefault(); const hit = navSearchHits(ui.navQ || "")[0]; if (hit) hotGo(hit[0]); return; }
    if (k === "Escape") { ev.preventDefault(); if (ui.navQ) { ui.navQ = ""; const id = document.activeElement.id; if (id === "navqm") navMenuSheet(); else renderNav(); const n = $("#" + id); if (n) n.focus(); } else document.activeElement.blur(); return; }
    return;
  }
  if (document.activeElement && document.activeElement.id === "onRenPseudo" && k === "Enter") { ev.preventDefault(); const b = $('[data-act="on-renpseudogo"]'); if (b && !b.disabled) b.click(); return; }
  if (document.activeElement && document.activeElement.id === "encQ" && k === "Escape" && ui.enc && ui.enc.q) { ev.preventDefault(); const b = $('[data-act="encqclear"]'); if (b) b.click(); return; } // 1.0.22.1 : Échap vide la recherche de l'Encyclopédie
  if (document.activeElement && document.activeElement.id === "renName" && (k === "Enter" || k === "Escape")) { ev.preventDefault(); const b = $(`.hb-renf [data-act="${k === "Enter" ? "rengo" : "rencancel"}"]`); if (b) b.click(); return; } // 0.1.50.1 : Entrée valide le nouveau nom, Échap annule
  if (k === "/" && !isEditing() && !ev.ctrlKey && !ev.metaKey && !ev.altKey && !$("#sheet").innerHTML) { ev.preventDefault(); searchOpen(); }
  else if (k === "Escape" && ($("#wtip") || $('#sheet .sheet-bg[data-act="closesheet"]'))) { // 1.1.0.1 : Échap ferme aussi la fenêtre ouverte (pas celles de connexion)
    if ($("#wtip")) tipLater();
    if (!isEditing() && $('#sheet .sheet-bg[data-act="closesheet"]')) { ev.preventDefault(); closeSheet(); render(); } }
  else if (hotkey(ev)) ev.preventDefault();
  else if ((k === "ArrowUp" || k === "ArrowDown") && !isEditing() && !ev.ctrlKey && !ev.metaKey && !ev.altKey && !ev.shiftKey && !$("#sheet").innerHTML && heroRailKey(k === "ArrowDown" ? 1 : -1)) ev.preventDefault();
});
/* 1.1 (Mathis 4A) : raccourcis clavier sur PC, une lettre par page ; les pages absentes (hors ligne) sont ignorées.
   D'autres pages de la 1.1 s'ajoutent ici avec leur lettre. */
const HOTKEYS = [["h", "home"], ["m", "world"], ["d", "dungeons"], ["c", "combat"], ["s", "exp"], ["j", "defi"], ["k", "koli"], ["b", "wb"], ["e", "team"], ["i", "inv"], ["r", "maitrise"],
  ["t", "metiers"], ["f", "forge"], ["q", "quests"], ["u", "succes"], ["n", "enc"], ["v", "hdv"], ["g", "guild"], ["l", "ladder"], ["a", "asc"], ["p", "pets"], ["y", "dofus"]];
const navHotkey = (k) => { if (!S || (S.settings && S.settings.keysOff)) return ""; const x = HOTKEYS.find(([, p]) => p === k); return x ? x[0].toUpperCase() : ""; }; // lot ergonomie (21/10) : la lettre s'affiche au survol dans le menu
const hotPages = () => { const out = ["home", "combat"]; NAV.forEach((F) => F.pages.forEach((p) => { if (p[0] !== "bug" && p[0] !== "admin") out.push(p[0]); })); return out; }; // 1.2.7.2 : les flèches ne butent plus sur Signaler un bug
function hotGo(k) { if (k === "bug" && window.BUGS) { window.BUGS.open(); return; } if (navSheet(k)) return; navGo(k); closeSheet(); render(); window.scrollTo(0, 0); }
function hotkey(ev) {
  const k = ev.key; if (!S || (S.settings && S.settings.keysOff) || isEditing() || ev.ctrlKey || ev.metaKey || ev.altKey) return false;
  if (window.matchMedia && !window.matchMedia("(min-width: 900px)").matches) return false; // PC seulement
  if (k === "?") { hotSheet(); return true; }
  if ($("#sheet").innerHTML) return false;
  if (k === "o" || k === "O") { optionsSheet(); return true; }
  if (k === "ArrowLeft" || k === "ArrowRight") { if (ev.shiftKey) return false; const L = hotPages(); const i = L.indexOf(navKey()); if (i < 0) return false; hotGo(L[(i + (k === "ArrowRight" ? 1 : L.length - 1)) % L.length]); return true; }
  if (ev.shiftKey || k.length !== 1) return false;
  const hit = HOTKEYS.find(([x]) => x === k.toLowerCase()); if (!hit || !hotPages().includes(hit[1])) return false;
  hotGo(hit[1]); return true;
}
function hotSheet() {
  const all = hotPages(); const row = (key, txt) => `<div class="hk-row"><kbd>${key}</kbd><span>${h(txt)}</span></div>`;
  openSheet(`<h2>Raccourcis clavier</h2><div class="hk-grid">${HOTKEYS.filter(([, p]) => all.includes(p)).map(([x, p]) => row(x.toUpperCase(), navName(p).replace(/^.* › /, ""))).join("")}
    ${row("O", "Options")}${row("1 à 9", "L'Ascension : lancer un sort ou prendre un choix")}${row("Entrée", "L'Ascension : finir le tour, lancer l'étage, valider")}${row("Échap", "L'Ascension : passer ou refuser")}${row("← →", "L'Ascension : changer de cible pendant ton tour")}${row("← →", "Page précédente ou suivante du menu")}${row("↑ ↓", "Héros précédent ou suivant")}${row("Ctrl K ou /", "Rechercher")}${row("Échap", "Fermer une fenêtre")}${row("?", "Cette liste")}</div>
    <p class="xs muted">Sur PC seulement. Ils ne s'activent pas quand tu écris dans un champ. Tu peux les couper dans Options › Jeu.</p>
    <div class="row"><button class="btn" data-act="closesheet">Fermer</button></div>`);
}
