    if (error) return;
    const c = {}; (data || []).forEach((x) => { c[x.rule] = x.n; }); E.DEFI_VOTE[wk] = c; ui.dfVoteC = { w: wk, c }; dfVoteDay = E.defiDay();
    if (E.defiSunday(E.defiDay())) { S.defiVoteRes = { w: wk, c }; dirty = true; }
