  const when = wait ? `Prochain changement possible le ${nx.toLocaleDateString("fr-FR", { day: "numeric", month: "long" })} à ${nx.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}.` : "";
